<script setup>import { ref,computed } from 'vue';import { RouterLink,RouterView,useRoute } from 'vue-router';import { ShoppingBag, Utensils, MapPin, ShieldCheck, X, Minus, Plus, Trash2, CheckCircle2 } from 'lucide-vue-next';import {api,money} from './api';const route=useRoute();const cart=ref(JSON.parse(localStorage.getItem('qb_cart')||'[]'));const openCart=ref(false);const checkoutOpen=ref(false);const busy=ref(false);const success=ref(null);const error=ref('');const form=ref({customer_name:'',email:'',phone:'',address:'',order_type:'delivery',payment_method:'cod',notes:''});const count=computed(()=>cart.value.reduce((n,p)=>n+p.quantity,0));const subtotal=computed(()=>cart.value.reduce((n,p)=>n+p.price*p.quantity,0));const fee=computed(()=>form.value.order_type==='delivery'?50:0);const total=computed(()=>subtotal.value+fee.value);function save(){localStorage.setItem('qb_cart',JSON.stringify(cart.value))}function add(p){const old=cart.value.find(x=>x.id===p.id);if(old)old.quantity=Math.min(old.quantity+1,p.stock);else cart.value.push({...p,quantity:1});save();openCart.value=true}function change(p,d){p.quantity+=d;if(p.quantity<=0)cart.value=cart.value.filter(x=>x.id!==p.id);save()}function remove(p){cart.value=cart.value.filter(x=>x.id!==p.id);save()}async function checkout(){busy.value=true;error.value='';try{const {data}=await api.post('/orders',{...form.value,items:cart.value.map(p=>({product_id:p.id,quantity:p.quantity}))});success.value=data.order;cart.value=[];save();openCart.value=false;checkoutOpen.value=false;}catch(e){error.value=e.response?.data?.message||Object.values(e.response?.data?.errors||{}).flat().join(' ')||'Could not place order. Please check that the API is running.'}finally{busy.value=false}}function closeSuccess(){success.value=null;window.location.href='/track?order='+encodeURIComponent(success.value?.order_number||'')} </script>
<template><div class="app-shell"><header class="topbar"><RouterLink to="/" class="brand"><span class="brand-mark"><Utensils :size="21"/></span><span>quick<span class="orange">bite</span><small>GOOD FOOD. GOOD MOOD.</small></span></RouterLink><nav><RouterLink to="/">Menu</RouterLink><RouterLink to="/track"><MapPin :size="16"/> Track order</RouterLink><RouterLink to="/admin" class="admin-link"><ShieldCheck :size="16"/> Admin</RouterLink><button class="cart-trigger" @click="openCart=true"><ShoppingBag :size="18"/> <span>Cart</span><b>{{count}}</b></button></nav></header><main><RouterView @add="add"/></main><footer><div class="footer-brand"><span class="brand-mark"><Utensils :size="18"/></span> quick<span class="orange">bite</span></div><span>Made fresh. Served fast. <b>© 2026 QuickBite</b></span></footer>
<div v-if="openCart" class="overlay" @click.self="openCart=false"><aside class="drawer"><div class="drawer-head"><div><p class="eyebrow">YOUR SELECTION</p><h2>Your cart <span class="muted">({{count}})</span></h2></div><button class="icon-btn" @click="openCart=false"><X/></button></div><div v-if="!cart.length" class="empty"><ShoppingBag :size="38"/><h3>Your cart is hungry</h3><p>Add something delicious from the menu.</p><button class="btn primary" @click="openCart=false">Explore menu</button></div><div v-else class="cart-content"><div v-for="p in cart" :key="p.id" class="cart-item"><img :src="p.image_url" :alt="p.name"/><div class="cart-item-info"><b>{{p.name}}</b><span>{{money(p.price)}}</span><div class="qty"><button @click="change(p,-1)"><Minus :size="13"/></button><span>{{p.quantity}}</span><button :disabled="p.quantity>=p.stock" @click="change(p,1)"><Plus :size="13"/></button><button class="remove" @click="remove(p)"><Trash2 :size="14"/></button></div></div><strong>{{money(p.price*p.quantity)}}</strong></div><div class="bill"><div><span>Subtotal</span><b>{{money(subtotal)}}</b></div><div><span>Delivery fee</span><b>{{money(fee)}}</b></div><div class="bill-total"><span>Total</span><strong>{{money(total)}}</strong></div><button class="btn primary wide" @click="checkoutOpen=true;openCart=false">Proceed to checkout <span>→</span></button><p class="secure-note">Cash on delivery or GCash · Secure checkout</p></div></div></aside></div>
<div v-if="checkoutOpen" class="overlay" @click.self="checkoutOpen=false"><section class="modal checkout-modal"><div class="drawer-head"><div><p class="eyebrow">ALMOST THERE</p><h2>Checkout</h2></div><button class="icon-btn" @click="checkoutOpen=false"><X/></button></div><form class="checkout-form" @submit.prevent="checkout"><label>Full name<input v-model="form.customer_name" required maxlength="120" placeholder="Your name"/></label><div class="form-row"><label>Phone number<input v-model="form.phone" required placeholder="09xx xxx xxxx"/></label><label>Email <span class="muted">(optional)</span><input v-model="form.email" type="email" placeholder="you@email.com"/></label></div><label>Delivery address / pickup notes<textarea v-model="form.address" required placeholder="Street, barangay, city or pickup name"></textarea></label><div class="form-row"><label>Order type<select v-model="form.order_type"><option value="delivery">Delivery (+ ₱50)</option><option value="pickup">Pickup (free)</option></select></label><label>Payment method<select v-model="form.payment_method"><option value="cod">Cash on delivery</option><option value="gcash">GCash</option></select></label></div><label>Order notes <span class="muted">(optional)</span><textarea v-model="form.notes" placeholder="Special instructions"></textarea></label><div v-if="error" class="alert">{{error}}</div><div class="checkout-total"><span>Order total</span><strong>{{money(total)}}</strong></div><button class="btn primary wide" :disabled="busy">{{busy?'Placing order…':'Place order · '+money(total)}}</button><p class="secure-note">GCash is recorded as a payment choice; payment verification is handled separately.</p></form></section></div>
<div v-if="success" class="overlay"><section class="modal success-modal"><div class="success-icon"><CheckCircle2 :size="40"/></div><p class="eyebrow">ORDER CONFIRMED</p><h2>You're in for a treat!</h2><p>Your order has been sent to the kitchen.</p><div class="order-code"><span>YOUR ORDER NUMBER</span><strong>{{success.order_number}}</strong></div><p class="muted">Save this number and use your phone number to track the order.</p><button class="btn primary wide" @click="()=>{const n=success.order_number;success=null;window.location.href='/track?order='+encodeURIComponent(n)}">Track my order →</button></section></div></div></template>